@startuml

class Person {
  + firstName
  + lastName
  + address
}

class CLIENT extends Person {
  + phoneNumber
  + contactPerson
}

class WORKER extends Person {
  + birthDate
  + skills: string[]
}

class MACHINE {
  + serialNumber
  + make
  + model
  + purchaseDate
}

class PRODUCT_TYPE {
  + material
  + weight
}

class PRODUCT {
  + id
}

class PURCHASEORDER {
  + orderNumber
  + dateMade
  + expectedDeliveryDate
  + actualDeliveryDate
}

class PRODUCTPURCHASEORDER {
  + quantity
}

WORKER "*" -- "*" MACHINE
MACHINE "1" -- "*" PRODUCT_TYPE
PRODUCT_TYPE "1" -- "*" PRODUCT
CLIENT "1" -- "*" PURCHASEORDER
PRODUCT "1" -- "*" PRODUCTPURCHASEORDER
PURCHASEORDER "1" -- "*" PRODUCTPURCHASEORDER

@enduml

